import type { ReactNode } from 'react'
import Sidebar from '@/components/Sidebar'
import './../../app/globals.css'
import UserHeader from '@/components/reusable/UserHeader'
import { auth } from '@/auth'
import { redirect } from 'next/navigation'

export const metadata = {
  title: 'FASTLANE Seller Dashboard',
  description: 'Manage your products, orders, and customers all in one place.',
}

export default async function RootLayout({
  children,
}: {
  children: ReactNode
}) {
  const session = await auth()

  if (!session?.user || session?.user?.role !== 'seller') {
    redirect('/seller-login')
  }

  return (
    <div className="bg-[#F3F4F6] min-h-screen flex">
      {/* Sidebar */}
      <Sidebar />

      {/* Main Content */}
      <main className="flex-1 flex flex-col">
        {/* Top Header */}
        <header className="bg-[#1C2228] shadow flex justify-end items-center py-5 pr-12">
          <UserHeader />
        </header>

        {/* Page Content */}
        <div className="flex-1 p-6">{children}</div>
      </main>
    </div>
  )
}
